-- 020 · Correções do acervo, lote 1 (pesquisa com fontes; ver api/lib/memepedia-acervo.js).
--  O banco é a fonte da verdade do acervo (o seed não sobrescreve), então as correções vêm por migração.
--  Cada UPDATE só vale se o campo ainda estiver com o texto antigo: o que o admin já editou fica como está.
--  'Aonde É Que Eu Tô? Sertãozinho!' era outro vídeo: o meme é 'Onde é que eu tô? Será que tô na Lagoinha?' (o id fica o mesmo).
-- Idempotente.
SET LOCAL lock_timeout = '5s';

UPDATE memes SET descricao = 'A sessão de autógrafos da banda Restart em São Paulo foi cancelada e a fã Georgia Massa, chorando, misturou “puta sacanagem” com “falta de respeito”. Nasceu o bordão do injusto.' WHERE id = 'puta-falta-de-sacanagem' AND descricao IS NOT DISTINCT FROM 'Sessão de autógrafos da banda Restart cancelada por superlotação gerou revolta, lágrimas e o bordão involuntário ''Puta falta de sacanagem!''.';
UPDATE memes SET data = '2010-04-28' WHERE id = 'puta-falta-de-sacanagem' AND data IS NOT DISTINCT FROM '2010-04-18';
UPDATE memes SET descricao = 'Reportagem de 2011 sobre Paulo David Amorim, de 11 anos, de Mossoró (RN), que grudava colheres, garfos e moedas no corpo e foi apresentado como “menino ímã”.' WHERE id = 'menino-ima' AND descricao IS NOT DISTINCT FROM 'Reportagem da Inter TV Cabugi (RN) sobre um menino que grudava colheres, garfos e moedas no corpo, apresentado como “menino ímã”.';
UPDATE memes SET descricao = 'Os irmãos Jefferson e Suellen ensaiam “Galhos Secos” no sofá com a mãe, Mara. No refrão, Jefferson solta o agudo, a mãe sai de cena e a irmã cai na risada.' WHERE id = 'para-nossa-alegria' AND descricao IS NOT DISTINCT FROM 'A família cantando no sofá quando o filho solta um agudo potente e desafinado que faz a mãe abandonar o quadro aos risos.';
UPDATE memes SET descricao = 'A mulher que foi a programas de TV dizendo esperar quadrigêmeas, ganhou doações e enganou o Brasil com uma barriga falsa, até a farsa ser revelada em janeiro de 2012.' WHERE id = 'gravida-de-taubate' AND descricao IS NOT DISTINCT FROM 'A mulher que enganou programas de televisão com uma barriga colossal de silicone dizendo estar grávida de quadrigêmeas.';
UPDATE memes SET descricao = 'Vídeo caseiro de 2014: Geovanna dança em cima da mesa apoiada num forninho até ele cair, e a prima que filmava grita “Eita, Geovanna! O forninho caiu!” e sai correndo contar para a mãe.' WHERE id = 'giovana-forninho' AND descricao IS NOT DISTINCT FROM 'A prima dançando funk apoiada num forninho elétrico de brinquedo até a estrutura ceder no momento exato do refrão.';
UPDATE memes SET titulo = 'Onde É Que Eu Tô? Será Que Tô na Lagoinha?' WHERE id = 'aonde-e-que-eu-to-sertaozinho' AND titulo IS NOT DISTINCT FROM 'Aonde É Que Eu Tô? Sertãozinho!';
UPDATE memes SET descricao = 'Um rapaz desnorteado pergunta “Onde é que eu tô? Será que tô na Lagoinha?” e a frase virou a resposta pronta de quem se perde, de lugar ou de assunto.' WHERE id = 'aonde-e-que-eu-to-sertaozinho' AND descricao IS NOT DISTINCT FROM 'Um rapaz meio perdido acorda da carona e pergunta em looping a sua localização geográfica no interior paulista.';
UPDATE memes SET data = '2020-12-26' WHERE id = 'aonde-e-que-eu-to-sertaozinho' AND data IS NOT DISTINCT FROM '2015-10-09';
UPDATE memes SET youtube_id = 'zbnwWlrN5mo' WHERE id = 'aonde-e-que-eu-to-sertaozinho' AND youtube_id IS NOT DISTINCT FROM 'L1EkzLJXkrM';
UPDATE memes SET ano = 2020 WHERE id = 'aonde-e-que-eu-to-sertaozinho' AND ano = 2015 AND titulo = 'Onde É Que Eu Tô? Será Que Tô na Lagoinha?';
UPDATE memes SET descricao = 'O funk de MC Bin Laden que manda fazer “o famoso sinal do Ronaldinho” estourou no fim de 2015 e virou a dancinha do começo de 2016, cantada até com Skrillex e Diplo no Lollapalooza.' WHERE id = 'ta-tranquilo-ta-favoravel' AND descricao IS NOT DISTINCT FROM 'O sinal de Ronaldinho Gaúcho com os dedos e o passinho sem camisa que virou febre nas praias e foi dançado até por Neymar.';
UPDATE memes SET descricao = 'Todo 11 de setembro o apresentador do Domingo Legal volta aos assuntos mais comentados por uma piada que o liga, sem motivo nenhum, aos atentados de 2001.' WHERE id = 'celso-portiolli-11-setembro' AND descricao IS NOT DISTINCT FROM 'A lenda urbana de que o apresentador do Domingo Legal jamais teve qualquer envolvimento com a queda das Torres Gêmeas.';
UPDATE memes SET autor = NULL, duracao = NULL WHERE id = 'aonde-e-que-eu-to-sertaozinho' AND autor = 'Web Caipira';
DELETE FROM midias WHERE meme_id = 'aonde-e-que-eu-to-sertaozinho' AND caminho = 'memes/aonde-e-q-eu-to-sertaozinho.jpg';
